CREATE OR ALTER PROCEDURE [dbo].[uspRecipeLine_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @RecipeId UNIQUEIDENTIFIER = NULL
	, @IngredientId UNIQUEIDENTIFIER = NULL
	, @UnitId UNIQUEIDENTIFIER = NULL
	, @Quantity DECIMAL(18,6) = NULL
	, @ExpectedWasteRate DECIMAL(18,4) = NULL
	, @PreparationNote NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[RecipeId]
			, t.[IngredientId]
			, j1.[Name] AS [IngredientName]
			, t.[Quantity]
			, t.[WastePercent]
			, t.[YieldPercent]
			, t.[SequenceNo]
			, t.[Note]
			, t.[UnitId]
			, j2.[Name] AS [UnitName]
			, t.[ExpectedWasteRate]
			, t.[PreparationNote]
			, t.[SortOrder]
			, t.[CreatedDate]
		FROM [dbo].[RecipeLine] AS t
		LEFT JOIN [dbo].[Ingredient] AS j1 ON j1.[Id] = t.[IngredientId]
		LEFT JOIN [dbo].[UnitMeasure] AS j2 ON j2.[Id] = t.[UnitId]
		WHERE 1 = 1
			AND (@RecipeId IS NULL OR t.[RecipeId] = @RecipeId)
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (@UnitId IS NULL OR t.[UnitId] = @UnitId)
			AND (@Quantity IS NULL OR t.[Quantity] = @Quantity)
			AND (@ExpectedWasteRate IS NULL OR t.[ExpectedWasteRate] = @ExpectedWasteRate)
			AND (ISNULL(@PreparationNote, '') = '' OR t.[PreparationNote] LIKE CONCAT('%', @PreparationNote, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recipeId' THEN r.[RecipeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recipeId' THEN r.[RecipeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientName' THEN r.[IngredientName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientName' THEN r.[IngredientName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'wastePercent' THEN r.[WastePercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'wastePercent' THEN r.[WastePercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'yieldPercent' THEN r.[YieldPercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'yieldPercent' THEN r.[YieldPercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sequenceNo' THEN r.[SequenceNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sequenceNo' THEN r.[SequenceNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitId' THEN r.[UnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitId' THEN r.[UnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitName' THEN r.[UnitName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitName' THEN r.[UnitName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expectedWasteRate' THEN r.[ExpectedWasteRate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expectedWasteRate' THEN r.[ExpectedWasteRate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'preparationNote' THEN r.[PreparationNote] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'preparationNote' THEN r.[PreparationNote] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sortOrder' THEN r.[SortOrder] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sortOrder' THEN r.[SortOrder] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
